import{_ as r,o as t,c as a,a3 as o}from"./chunks/framework.BWzgKoSO.js";const c=JSON.parse('{"title":"附 E　来源全表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/e-sources.md","filePath":"appendix/e-sources.md","lastUpdated":1793338243000}'),n={name:"appendix/e-sources.md"};function s(i,e,g,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="附-e-来源全表" tabindex="-1">附 E　来源全表 <a class="header-anchor" href="#附-e-来源全表" aria-label="Permalink to &quot;附 E　来源全表&quot;">​</a></h1><p>这里放正文里所有编号的完整条目。每一条我都点到过原文，能点的都会给出链接。</p><h2 id="怎么读这张表" tabindex="-1">怎么读这张表 <a class="header-anchor" href="#怎么读这张表" aria-label="Permalink to &quot;怎么读这张表&quot;">​</a></h2><p><strong>等级</strong>：<strong>A</strong> 官方指南、国标、系统综述或大样本随机对照试验　<strong>B</strong> 单项随机对照试验、队列研究　<strong>C</strong> 机制推断、小样本、个人经验</p><p><strong>编号</strong>：G 是官方文件，R 是论文与研究，S 是平台与产品数据。</p><p>正文里只写编号，是为了让段落能读下去。你要核的时候来这里。</p><h2 id="g-系列-官方文件" tabindex="-1">G 系列　官方文件 <a class="header-anchor" href="#g-系列-官方文件" aria-label="Permalink to &quot;G 系列　官方文件&quot;">​</a></h2><p><strong>G1｜《成人肥胖食养指南（2024 年版）》</strong>〔A〕 国家卫生健康委员会，2024 年 2 月发布。 用到的地方：0.2 每周减重的速度上限；2.2 缺口 500～1000 千卡与男女下限；2.4 三大营养素供能比与三餐 3:4:3；3.3 进餐顺序；3.7 油盐上限；4.2 运动处方与久坐时间；6.2 平台期是标准情形。 原文位置：能量与供能比在正文第 5 页；进餐顺序在第 8 页；运动处方在第 8 页；减重速度在第 9 页。 链接：<a href="https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476136267_20714.pdf" target="_blank" rel="noreferrer">https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476136267_20714.pdf</a></p><p><strong>G2｜《中国居民膳食指南（2022）》</strong>〔A〕 中国营养学会编著，人民卫生出版社。 用到的地方：3.4 每日饮水量（男 1700 毫升、女 1500 毫升，准则六）；3.5 与 3.7 食盐不超过 5 克、烹调油 25～30 克（准则四）；4.6 每天主动身体活动 6000 步（准则二）。 链接：<a href="http://dg.cnsoc.org/article/04/wDCyy7cWSJCN6pwKHOo5Dw.html" target="_blank" rel="noreferrer">http://dg.cnsoc.org/article/04/wDCyy7cWSJCN6pwKHOo5Dw.html</a></p><p><strong>G3｜GB 28050《预包装食品营养标签通则》</strong>〔A〕 现行版本 GB 28050-2011；新版 GB 28050-2025 于 2025 年 3 月 16 日发布，2027 年 3 月 16 日实施，替代 2011 版。 用到的地方：1.7 与 3.5 的“无糖”“无能量”判定线。 含量声称的阈值（两版一致）：无糖 ≤0.5 克/100 克（或 100 毫升）；低糖 ≤5 克/100 克；无脂肪 ≤0.5 克/100 克；低脂肪 固体 ≤3 克/100 克、液体 ≤1.5 克/100 毫升；无能量 ≤17 千焦/100 克（或 100 毫升），且脂肪供能比 ≤50%。 新版另有一处值得知道的变化：强制标示从“1+4”升级为“1+6”，增加了饱和脂肪（酸）和糖。</p><p><strong>G4｜《美国居民膳食指南（2025—2030）》</strong>〔A〕 美国农业部与卫生与公众服务部。 用到的地方：3.2 蛋白质目标 1.2～1.6 克/公斤体重/天（按个人热量需求调整）。 链接：<a href="https://cdn.realfood.gov/DGA.pdf" target="_blank" rel="noreferrer">https://cdn.realfood.gov/DGA.pdf</a></p><p><strong>G5｜《Use of non-sugar sweeteners: WHO guideline》</strong>〔A〕 世界卫生组织，2023 年 5 月。 用到的地方：1.7 不建议把非糖甜味剂当作控制体重的手段。 链接：<a href="https://www.who.int/publications/i/item/9789240073616" target="_blank" rel="noreferrer">https://www.who.int/publications/i/item/9789240073616</a></p><p><strong>G6｜美国国家医学院（IOM）膳食营养素参考摄入量：碳水 RDA 130 克/天</strong>〔A〕 Dietary Reference Intakes for Energy, Carbohydrate, Fiber, Fat, Fatty Acids, Cholesterol, Protein, and Amino Acids，2005 年，第 6 章。依据是大脑每天需要的葡萄糖量。 用到的地方：2.4 碳水底线。</p><p><strong>G7｜《中国食物成分表》第 6 版</strong>〔B〕 杨月欣主编，北京大学医学出版社，2018 年。 用到的地方：2.4 与 3.1 的换算式。 关键条目：米饭（蒸）每 100 克 116 千卡，蛋白质 2.6 克，脂肪 0.3 克，碳水 25.9 克；馒头每 100 克 223 千卡。</p><p><strong>G8｜《成人体重判定》WS/T 428-2013</strong>〔A〕 国家卫生和计划生育委员会发布。 用到的地方：4.1 BMI 24～27.9 为超重、≥28 为肥胖；腰围男性 ≥90 厘米、女性 ≥85 厘米为中心型肥胖。</p><p><strong>G9｜《肥胖症诊疗指南（2024 年版）》</strong>〔A〕 国家卫生健康委员会，2024 年 10 月。 用到的地方：7.1 减重期与维持期的有氧处方；7.3 术后“比最低点反弹超 15%”算体重反弹；8.3 两药的适应证、剂量、禁忌、副作用、停药反弹、肌少性肥胖。 原文位置：治疗目标在第 23 页；运动处方（减重期 150～420 分钟、维持期 200～300 分钟、抗阻每周 2～3 次取 50%～70% 最大负荷）在第 28 页；GLP-1 停药反弹与肌少性肥胖在第 39～40 页；司美格鲁肽与替尔泊肽条目在第 36～38 页。 链接：<a href="https://www.nhc.gov.cn/wjw/c100378/202410/bcf804e19e0c4246b5aea6cd338b55e1/files/1732873189749_61795.pdf" target="_blank" rel="noreferrer">https://www.nhc.gov.cn/wjw/c100378/202410/bcf804e19e0c4246b5aea6cd338b55e1/files/1732873189749_61795.pdf</a></p><p><strong>G10｜诺和盈与穆峰达在中国的获批与上市</strong>〔A〕 诺和盈（减重版司美格鲁肽）：2024 年 6 月 25 日获国家药监局批准减重适应症，2024 年 11 月 17 日上市。适应症门槛 BMI ≥30，或 BMI 27～30 且至少一种体重相关合并症。 穆峰达（替尔泊肽）：2024 年 5 月获批糖尿病适应症，2024 年 7 月 19 日获批减重适应症，2025 年 1 月 2 日上市。减重门槛 BMI ≥28，或 BMI ≥24 且至少一种合并症。 用到的地方：8.3。</p><h2 id="r-系列-论文与研究" tabindex="-1">R 系列　论文与研究 <a class="header-anchor" href="#r-系列-论文与研究" aria-label="Permalink to &quot;R 系列　论文与研究&quot;">​</a></h2><p><strong>R1｜局部肌肉训练对局部脂肪的影响</strong>〔B〕 Ramírez-Campillo R, Andrade DC, Campos-Jara C, Henríquez-Olguín C, Alvarez-Lepín C, Izquierdo M. Regional fat changes induced by localized muscle endurance resistance training. <em>J Strength Cond Res</em>. 2013;27:2219-2224. DOI：<a href="https://doi.org/10.1519/JSC.0b013e31827e8681" target="_blank" rel="noreferrer">https://doi.org/10.1519/JSC.0b013e31827e8681</a> 样本 11 人，只练一条腿，12 周、每周 3 次。练的那条腿脂肪无显著变化，全身脂肪降 5.1%。</p><p><strong>R2｜六周腹部训练</strong>〔B〕 Vispute SS, Smith JD, LeCheminant JD, Hurley KS. The effect of abdominal exercise on abdominal fat. <em>J Strength Cond Res</em>. 2011;25(9):2559-2564. DOI：<a href="https://doi.org/10.1519/JSC.0b013e3181fb4a46" target="_blank" rel="noreferrer">https://doi.org/10.1519/JSC.0b013e3181fb4a46</a> 样本 24 人，7 个腹部动作、2 组 10 次、每周 5 天、共 6 周。体重、体脂率、腰围、腹部皮褶均无显著变化，卷腹次数显著增加。</p><p><strong>R3｜饮食记录里的低报</strong>〔B〕 Poslusna K, Ruprich J, de Vries JHM, Jakubikova M, van&#39;t Veer P. Misreporting of energy and micronutrient intake estimated by food records and 24 hour recalls, control and adjustment methods in practice. <em>Br J Nutr</em>. 2009;101(S2):S73-S85. DOI：<a href="https://doi.org/10.1017/S0007114509990602" target="_blank" rel="noreferrer">https://doi.org/10.1017/S0007114509990602</a> 纳入 37 项研究，系统讨论低报的规模、成因与识别方法。</p><p><strong>R4｜TREAT：限时进食 vs 单纯限热量</strong>〔A〕 Liu D, et al. Calorie Restriction with or without Time-Restricted Eating in Weight Loss. <em>N Engl J Med</em>. 2022;386(16):1495-1504. DOI：<a href="https://doi.org/10.1056/NEJMoa2114833" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2114833</a></p><p><strong>R5｜16:8 的 12 周试验</strong>〔A〕 Lowe DA, et al. Effects of Time-Restricted Eating on Weight Loss and Other Metabolic Parameters in Women and Men With Overweight and Obesity. <em>JAMA Intern Med</em>. 2020;180(11):1491. DOI：<a href="https://doi.org/10.1001/jamainternmed.2020.4153" target="_blank" rel="noreferrer">https://doi.org/10.1001/jamainternmed.2020.4153</a></p><p><strong>R6｜Cochrane：间歇性断食</strong>〔A〕 Garegnani LI, Oltra G, Ivaldi D, 等. Intermittent fasting for adults with overweight or obesity. <em>Cochrane Database Syst Rev</em>. 2026;2:CD015610. DOI：<a href="https://doi.org/10.1002/14651858.CD015610.pub2" target="_blank" rel="noreferrer">https://doi.org/10.1002/14651858.CD015610.pub2</a> 说明：编号 CD015610 在 2023 年先出过一版方案（protocol），带结论的正式版是 2026 年 2 月这版。网上流传的“2025 年 Cochrane 那篇”，多半指的就是这个系列。</p><p><strong>R7｜BMJ 网状 meta 分析：各种断食方案</strong>〔A〕 Semnani-Azad Z, Khan TA, Chiavaroli L, 等. Intermittent fasting strategies and their effects on body weight and other cardiometabolic risk factors: systematic review and network meta-analysis of randomised clinical trials. <em>BMJ</em>. 2025;389:e082007. DOI：<a href="https://doi.org/10.1136/bmj-2024-082007" target="_blank" rel="noreferrer">https://doi.org/10.1136/bmj-2024-082007</a> 99 项随机试验、6,582 人。与持续限热量相比，只有隔日禁食有减重优势：平均多减 1.29 公斤（95% CI −1.99 至 −0.59）。</p><p><strong>R8｜Mifflin-St Jeor 公式</strong>〔B〕 Mifflin MD, St Jeor ST, Hill LA, Scott BJ, Daugherty SA, Koh YO. A new predictive equation for resting energy expenditure in healthy individuals. <em>Am J Clin Nutr</em>. 1990;51:241-247. DOI：<a href="https://doi.org/10.1093/ajcn/51.2.241" target="_blank" rel="noreferrer">https://doi.org/10.1093/ajcn/51.2.241</a> 样本 498 人。男：10×体重＋6.25×身高－5×年龄＋5；女：10×体重＋6.25×身高－5×年龄－161。</p><p><strong>R9｜餐前喝水</strong>〔B〕 Dennis EA, Dengo AL, Comber DL, 等. Water Consumption Increases Weight Loss During a Hypocaloric Diet Intervention in Middle-aged and Older Adults. <em>Obesity</em>. 2010;18(2):300-307. DOI：<a href="https://doi.org/10.1038/oby.2009.235" target="_blank" rel="noreferrer">https://doi.org/10.1038/oby.2009.235</a> 48 人，55～75 岁，BMI 25～40。餐前 500 毫升水＋低热量饮食 12 周，比只做低热量饮食的那组多减约 2 公斤。</p><p><strong>R10｜碳循环</strong>〔C〕 把 “carbohydrate cycling” 当主题词检索，没有找到针对减重结局的随机对照试验。此编号代表“查过、没有”，不是一条文献。 用到的地方：3.9。</p><p><strong>R11｜先吃菜再吃主食对血糖的影响</strong>〔B〕 Kampmann-Gongoll K, Schlesinger S, Noreik M, Kuss O, Lang A. Effect of eating vegetables before carbohydrates on glucose, insulin and glycemic control — a systematic review and meta-analysis of randomized controlled trials. <em>Clin Nutr</em>. 2026;66:106775. DOI：<a href="https://doi.org/10.1016/j.clnu.2026.106775" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.clnu.2026.106775</a> 18 项随机试验。餐后 30 分钟与 60 分钟的血糖、胰岛素确实降低，但 10 项被评为中等偏倚风险、8 项为高风险，证据确定性“很低”。</p><p><strong>R12｜极端减重后的长期代谢适应</strong>〔B〕 Fothergill E, Guo J, Howard L, 等. Persistent metabolic adaptation 6 years after “The Biggest Loser” competition. <em>Obesity</em>. 2016;24:1612-1619. DOI：<a href="https://doi.org/10.1002/oby.21538" target="_blank" rel="noreferrer">https://doi.org/10.1002/oby.21538</a> 16 人参赛，6 年后 14 人回访。比赛结束时平均减 58.3 公斤；6 年后回来 41.0 公斤；静息消耗比按体重推算的低 499 千卡/天。</p><p><strong>R13｜STEP-1 与它的停药延伸研究</strong>〔A／B〕 主体：Wilding JPH, 等. Once-Weekly Semaglutide in Adults with Overweight or Obesity. <em>N Engl J Med</em>. 2021;384(11):989-1002. DOI：<a href="https://doi.org/10.1056/NEJMoa2032183%EF%BC%8868" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2032183（68</a> 周平均减 14.9%，安慰剂组 2.4%） 延伸：Wilding JPH, 等. Weight regain and cardiometabolic effects after withdrawal of semaglutide: The STEP 1 trial extension. <em>Diabetes Obes Metab</em>. 2022;24:1553-1564. DOI：<a href="https://doi.org/10.1111/dom.14725%EF%BC%88327" target="_blank" rel="noreferrer">https://doi.org/10.1111/dom.14725（327</a> 人，治疗期平均减 17.3%，停药一年回来 11.6 公斤）</p><p><strong>R14｜SURMOUNT-1 与 SURMOUNT-4</strong>〔A／B〕 主体：Jastreboff AM, 等. Tirzepatide Once Weekly for the Treatment of Obesity. <em>N Engl J Med</em>. 2022;387(3):205-216. DOI：<a href="https://doi.org/10.1056/NEJMoa2206038%EF%BC%8872" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2206038（72</a> 周平均减 15%～21%） 停药：Aronne LJ, 等. Continued Treatment With Tirzepatide for Maintenance of Weight Reduction in Adults With Obesity: The SURMOUNT-4 Trial. <em>JAMA</em>. 2024. DOI：<a href="https://doi.org/10.1001/jama.2023.24945%EF%BC%88%E5%85%88%E7%94%A8" target="_blank" rel="noreferrer">https://doi.org/10.1001/jama.2023.24945（先用</a> 36 周降 20.9%；之后继续用药再降 5.5%，换安慰剂回升 14.0%）</p><h2 id="s-系列-平台与产品" tabindex="-1">S 系列　平台与产品 <a class="header-anchor" href="#s-系列-平台与产品" aria-label="Permalink to &quot;S 系列　平台与产品&quot;">​</a></h2><p><strong>S1｜麦当劳中国巨无霸营养信息</strong>〔A〕 每份能量 2146 千焦，约 513 千卡；蛋白质 27 克，脂肪 26 克，碳水 42 克，钠 961 毫克。 链接：<a href="https://www.mcdonalds.com.cn/product/Big-Mac" target="_blank" rel="noreferrer">https://www.mcdonalds.com.cn/product/Big-Mac</a> 用到的地方：1.6、2.2。</p><p><strong>S2｜Free Exercise DB（动作示范照片）</strong>〔B〕 yuhonas/free-exercise-db，870 余个动作，每个动作两张照片（起始、到位），数据集以 Unlicense 释出，属公有领域，可自由使用与改写。 链接：<a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noreferrer">https://github.com/yuhonas/free-exercise-db</a> 用到的地方：4.4 的 19 张分解图。我把每个动作的起止两帧拼成一张，加了标号与要点；照片本身没有改动动作、没有重绘。</p><h2 id="作者自己那一份" tabindex="-1">作者自己那一份 <a class="header-anchor" href="#作者自己那一份" aria-label="Permalink to &quot;作者自己那一份&quot;">​</a></h2><p>第零部分、第五部分里关于减重经历的叙述，第一人称，来自本人；体重、体脂、BMI 的数字取自体脂秤截图，两张截图都在第零部分。</p><p><strong>我没有做的</strong>：这本书里没有一项数据是我自己测的。体重之外的身体成分、代谢指标、训练量，我一个都没测过。所以凡是讲到“我怎么做的”，只到我确实做过的那一步为止。</p><h2 id="怎么自己核" tabindex="-1">怎么自己核 <a class="header-anchor" href="#怎么自己核" aria-label="Permalink to &quot;怎么自己核&quot;">​</a></h2><p>官方文件去卫健委官网或中国营养学会官网找，都是免费 PDF。</p><p>论文用 DOI 打开，摘要里的“结果”“结论”两段必看。免费全文在 PubMed Central、Europe PMC 上找。</p><p>找不到原文、只看到转述，就把那条当线索，不当依据。</p><hr><p>这篇附录会长，但它比正文更该被挑刺。哪一条点不开、哪一句和原文对不上，去仓库提 issue，我改。</p>',44)])])}const f=r(n,[["render",s]]);export{c as __pageData,f as default};
